'use strict';
const {KEY,defaults,validate,save,daysTogether}=WorldCore;
const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name,cls='')=>`<svg class="${cls}" aria-hidden="true"><use href="#i-${name}"/></svg>`;
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const dateLabel=s=>new Date(s+'T12:00:00').toLocaleDateString('en',{day:'numeric',month:'short',year:'numeric'});
let state=defaults(),loadError='',photoDraft='',photoBusy=false,toastTimer,promptDeck=[],promptCount=0,lastDate=-1;
try{const raw=localStorage.getItem(KEY);if(raw)state=validate(JSON.parse(raw));}catch{loadError='Your saved world couldn’t be read. Nothing has been overwritten. Try restoring a backup from settings.';}
const main=$('#main'),modal=$('#modal');
function notify(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),6500);}
function commit(update){if(loadError)throw Error('Your saved world needs restoring first. Open settings to restore a backup; existing data has been preserved.');const next=structuredClone(state);update(next);state=save(localStorage,next);render();}
function currentPage(){const value=location.hash.slice(1);return ['home','memories','notes','together'].includes(value)?value:'home';}
function names(){return `${esc(state.profile.one)} & ${esc(state.profile.two)}`;}
function btn(label,action,style='',ico=''){return `<button type="button" class="button ${style}" data-action="${action}">${ico?icon(ico):''}${label}</button>`;}
function modalHeader(title,kicker='A LITTLE SOMETHING FOR US'){return `<div class="modal-header"><div><div class="eyebrow">${kicker}</div><h2 id="dialog-title">${title}</h2></div><button class="icon-button" data-action="close" aria-label="Close dialog">${icon('close')}</button></div>`;}
function openDialog(content){$('#modal-content').innerHTML=content;if(!modal.open)modal.showModal();}
function scene(){return `<div class="scene-wrap"><svg class="night-scene" viewBox="0 0 480 350" role="img" aria-labelledby="scene-title scene-description" xmlns="http://www.w3.org/2000/svg"><title id="scene-title">Our little moonlit hideaway</title><desc id="scene-description">Two cats, one lavender and one peach, sit close together at an arched window under the same moon.</desc><defs><linearGradient id="window-sky" x2="0" y2="1"><stop stop-color="#3c3357"/><stop offset="1" stop-color="#736484"/></linearGradient><linearGradient id="window-frame" x2="1" y2="1"><stop stop-color="#514360"/><stop offset="1" stop-color="#30283f"/></linearGradient><linearGradient id="hill" x2="0" y2="1"><stop stop-color="#71617e"/><stop offset="1" stop-color="#40334e"/></linearGradient><radialGradient id="moon-glow"><stop stop-color="#eddbb0" stop-opacity=".25"/><stop offset="1" stop-color="#eddbb0" stop-opacity="0"/></radialGradient><clipPath id="arch"><path d="M117 281V145a123 123 0 0 1 246 0v136Z"/></clipPath></defs><ellipse cx="245" cy="305" rx="174" ry="15" fill="#0b0912" opacity=".25"/><path d="M102 285V145a138 138 0 0 1 276 0v140Z" fill="url(#window-frame)" stroke="#9d83b1" stroke-opacity=".2"/><path d="M112 282V145a128 128 0 0 1 256 0v137Z" fill="#211c31" stroke="#c4b0dc" stroke-opacity=".16"/><g clip-path="url(#arch)"><rect x="117" y="20" width="246" height="267" fill="url(#window-sky)"/><circle class="glow-orb" cx="288" cy="95" r="91" fill="url(#moon-glow)"/><path d="M310 62a35 35 0 1 0 14 60 37 37 0 0 1-14-60" fill="#f2dfb2"/><g fill="#e9d9ee"><circle cx="173" cy="123" r="1.5"/><circle cx="206" cy="67" r="1"/><circle cx="246" cy="113" r="1.1"/><circle cx="330" cy="151" r="1.2"/><circle cx="146" cy="175" r="1"/><circle cx="228" cy="160" r="1"/><circle cx="291" cy="169" r=".8"/></g><path d="m185 83 2 7 7 2-7 2-2 7-2-7-7-2 7-2Z" fill="#e9d9ee" class="star-twinkle"/><path d="m335 108 1 4 4 1-4 1-1 4-1-4-4-1 4-1Z" fill="#e9d9ee" class="star-twinkle late"/><path d="M104 225q56-73 130-21t144-3v100H104" fill="#8c7898" opacity=".5"/><path d="M94 250q68-64 140-12t150-8v70H94" fill="url(#hill)"/><path d="M115 276q86-58 140-22t120-12v60H115" fill="#3f344e"/></g><path d="M240 25v200M117 178h246" stroke="#332a43" stroke-width="6"/><path d="M240 25v200M117 178h246" stroke="#a892ba" stroke-opacity=".2" stroke-width="1"/><path d="M94 282h292v12H94Z" fill="#60506c"/><path d="M88 294h304v6H88Z" fill="#372c45"/><g><path d="M194 281c-13-2-22-12-21-26 1-11 8-24 11-34l-1-28 16 12c10-3 21-3 31 0l15-12-1 28c8 16 13 31 9 44-3 10-10 17-22 18Z" fill="#b3a0c7"/><path d="M194 218q7 5 13 0m13 0q7 5 13 0" fill="none" stroke="#56435f" stroke-width="2"/><path d="m211 226 4 3 4-3" stroke="#80617f" fill="none"/><path d="M184 272c-36-6-37 18-7 20h36" stroke="#b3a0c7" stroke-width="11" fill="none" stroke-linecap="round"/><path d="M259 282c-12-2-18-11-17-25 1-11 7-22 11-32l-2-24 15 11c9-3 18-3 26 0l13-11-1 25c8 17 11 31 7 41-4 10-11 15-21 16Z" fill="#d8b1b1"/><path d="M260 224q6 5 12 0m12 0q6 5 12 0" fill="none" stroke="#79535b" stroke-width="2"/><path d="m274 233 4 3 4-3" stroke="#a5757c" fill="none"/><path d="M300 273c33-5 32 17 7 19h-29" stroke="#d8b1b1" stroke-width="10" fill="none" stroke-linecap="round"/><path d="M219 277q16 12 33 1" fill="none" stroke="#ccb6d0" stroke-width="5" stroke-linecap="round"/></g><path d="M68 279v-38m0 18q-17-3-15-18 16 1 15 18m0-7q17-4 14-17-14 1-14 17" fill="#766e85" stroke="#766e85" stroke-width="2"/><path d="m53 274 4 20h23l4-20Z" fill="#958296"/><path d="M399 270v-17" stroke="#d5b483" stroke-width="6"/><rect x="390" y="267" width="19" height="27" rx="2" fill="#bda194"/><path d="M399 254q-9-9 0-18 8 10 0 18" fill="#efcc8f"/><circle cx="399" cy="248" r="27" fill="url(#moon-glow)"/><g fill="#d5b9df"><path class="star-twinkle" d="m75 101 2 7 7 2-7 2-2 7-2-7-7-2 7-2Z"/><path class="star-twinkle late" d="m405 157 2 6 6 2-6 2-2 6-2-6-6-2 6-2Z"/><circle cx="88" cy="177" r="1.4"/><circle cx="403" cy="84" r="1.5"/><circle cx="421" cy="222" r="1"/></g><path d="M405 53q14-17 31-5" stroke="#aa8cba" stroke-width="1" stroke-dasharray="3 5" fill="none"/><text x="432" y="55" fill="#dfc798" font-size="16">♡</text></svg><div class="scene-caption">my favorite place is next to you.</div></div>`;}
function home(){const memory=state.memories[0];const count=state.profile.anniversary?daysTogether(state.profile.anniversary,today()):null;return `<section class="hero"><div class="hero-copy"><div class="eyebrow"><span class="tiny-star">✧</span> THE ${names()} UNIVERSE</div><h1>Somewhere only<br><em>we belong.</em></h1><p class="hero-description">A tiny corner of the universe for our memories,<br>our little love notes, and a little more us.</p><div class="actions">${btn('Leave a little love','new-note','','heart')}<a class="quiet-link" href="#together">Spend time together ${icon('arrow')}</a></div><div class="hero-footnote">${icon('spark')} Two people. One very cozy little world.</div></div>${scene()}</section>${count&&count>0?`<div class="anniversary-strip">${icon('heart')}<span><strong>${count.toLocaleString()} days</strong> of choosing each other. And counting. <span aria-hidden="true">♡</span></span></div>`:''}<section><div class="section-heading"><div><h2>A little closer tonight</h2><p>Little things. Big feelings.</p></div><span class="eyebrow" style="font-size:8px;color:#a99bb8">JUST THE TWO OF US</span></div><div class="ritual-grid"><button class="ritual-card" data-action="prompt"><div class="card-symbol">${icon('spark')}</div>${icon('arrow','card-arrow')}<h3>One more little question</h3><p>Go from “how was your day?” to a little closer.</p><span class="card-tag">TAKE TURNS · TAKE YOUR TIME</span></button><button class="ritual-card" data-action="new-note"><div class="card-symbol gold">${icon('mail')}</div>${icon('arrow','card-arrow')}<h3>Words to keep</h3><p>The cheesy thought you haven’t told them yet.</p><span class="card-tag">WRITE IT · FOLD IT · KEEP IT</span></button><button class="ritual-card" data-action="date"><div class="card-symbol blue">${icon('heart')}</div>${icon('arrow','card-arrow')}<h3>Tonight, let’s...</h3><p>A tiny date idea. A very good excuse to stay close.</p><span class="card-tag">A LITTLE SPONTANEITY</span></button></div></section><section><div class="section-heading"><div><h2>Our pocket of forever</h2><p>Even the ordinary days deserve a place.</p></div><a class="quiet-link" href="#memories">Visit the shelf ${icon('arrow')}</a></div><div class="home-bottom"><div class="shelf-preview">${memory?(memory.photo?`<img class="preview-photo" src="${esc(memory.photo)}" alt="${esc(memory.title)}">`:'<div class="preview-no-photo" aria-hidden="true">☾</div>'):'<div class="mini-polaroids" aria-hidden="true"><div class="mini-polaroid"><span>✧</span></div><div class="mini-polaroid"><span>☾</span></div></div>'}<div><h3>${memory?esc(memory.title):'Our next favorite memory'}</h3><p>${memory?esc(dateLabel(memory.date)):'The blurry photo. The inside joke. The day we did absolutely nothing.'}</p><button class="quiet-link text-button" data-action="${memory?'memory':'new-memory'}" ${memory?`data-id="${esc(memory.id)}"`:''}>${memory?'Open this memory':'Keep a little moment'} ${icon('arrow')}</button></div></div><div class="quote-card"><div class="eyebrow">A LITTLE REMINDER</div><blockquote>“Out of all the stars,<br>I’d still find you.”</blockquote><span class="quote-star" aria-hidden="true">✧</span></div></div></section>`;}
function memoryPage(){return `<div class="page-intro"><div><div class="eyebrow">THE GOOD STUFF, KEPT CLOSE</div><h1>Our memory <em>shelf.</em></h1><p>Big adventures, tiny moments, and all the wonderfully ordinary in between.</p></div>${btn('Keep a moment','new-memory','','plus')}</div>${state.memories.length?`<div class="memory-grid">${state.memories.map(m=>`<button class="memory-card" data-action="memory" data-id="${esc(m.id)}">${m.photo?`<img src="${esc(m.photo)}" alt="${esc(m.title)}" loading="lazy">`:'<div class="memory-placeholder" aria-hidden="true">☾</div>'}<h2>${esc(m.title)}</h2><p>${esc(dateLabel(m.date))} · ${names()}</p></button>`).join('')}</div>`:`<div class="empty-state"><div class="empty-art" aria-hidden="true">☾ ♡</div><h2>Someday, we’ll say “remember when?”</h2><p>Give that moment a home. Add a photo, a little story, or just a sentence you never want to forget.</p>${btn('Our first little memory','new-memory','','plus')}</div>`}<p class="private-footnote">${icon('lock')} Kept in this browser. Download a backup in settings to keep a copy.</p>`;}
function notesPage(){return `<div class="page-intro"><div><div class="eyebrow">SOME FEELINGS DESERVE PAPER</div><h1>Little love <em>notes.</em></h1><p>A place for the sweet, the silly, and the very, very cheesy.</p></div>${btn('Write a little note','new-note','','mail')}</div>${state.notes.length?`<div class="note-grid">${state.notes.map(n=>`<button class="note-envelope" data-action="note" data-id="${esc(n.id)}"><span class="seal" aria-hidden="true">♡</span><h2>For ${esc(n.to)}</h2><p>A little love from ${esc(n.from)}</p><span class="open-label">TAP TO UNFOLD</span></button>`).join('')}</div>`:`<div class="empty-state"><div class="empty-art" aria-hidden="true">✉ ♡</div><h2>Your words. Their favorite keepsake.</h2><p>“I love the way you...” is a pretty good place to start. Leave a note for your favorite human.</p>${btn('Leave the first love note','new-note','','heart')}</div>`}<p class="private-footnote">${icon('lock')} Folded for the surprise. Anyone using this browser can open these notes.</p>`;}
function togetherPage(){return `<div class="page-intro"><div><div class="eyebrow">A LITTLE LESS SCROLLING, A LITTLE MORE US</div><h1>Just us <em>time.</em></h1><p>Sit close. Put the world on pause. You don’t need a special occasion.</p></div></div><div class="together-grid"><div class="together-card"><span class="big-icon" aria-hidden="true">✧</span><h2>Meet me a little deeper</h2><p>Sweet questions, silly questions, and a few that make you fall for each other all over again. Take turns answering.</p>${btn('Pick a question','prompt','','spark')}</div><div class="together-card"><span class="big-icon" aria-hidden="true">☾</span><h2>Our tiny date jar</h2><p>Little dates for a lovely night in. Low effort, lots of us. Pick one and see where the evening goes.</p>${btn('Pick tonight’s date','date','secondary','heart')}</div></div><div class="little-promise">“We don’t have to do anything extraordinary.<br>I just like doing life with you.”<span>${names()}</span></div>`;}
function render(){const page=currentPage();main.innerHTML=({home,memories:memoryPage,notes:notesPage,together:togetherPage}[page])();main.classList.remove('view-enter');void main.offsetWidth;main.classList.add('view-enter');document.querySelectorAll('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===page);if(a.dataset.nav===page)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#memory-count').textContent=state.memories.length||'';$('#note-count').textContent=state.notes.length||'';$('.side-bottom strong').textContent=`${state.profile.one} & ${state.profile.two}`;const avatars=document.querySelectorAll('.couple-orbits span');avatars[0].textContent=state.profile.one.slice(0,1);avatars[1].textContent=state.profile.two.slice(0,1);$('footer>span:last-child').innerHTML=`${esc(state.profile.one)} <i>♡</i> ${esc(state.profile.two)}`;document.title=`${state.profile.one} & ${state.profile.two} · Our Little World`;}
function newMemory(){photoDraft='';photoBusy=false;openDialog(`${modalHeader('Keep this little moment.')}<form id="memory-form" class="modal-body"><label class="field"><span>Give it a little name</span><input name="title" maxlength="100" placeholder="That night we couldn’t stop laughing" required></label><label class="field"><span>When was it?</span><input type="date" name="date" value="${today()}" max="${today()}" required></label><label class="field"><span>The bit we want to remember <small style="display:inline">(optional)</small></span><textarea name="body" maxlength="3000" placeholder="What made this moment ours?"></textarea></label><label class="upload-zone"><input id="photo-input" type="file" accept="image/jpeg,image/png,image/webp"><span id="photo-preview">${icon('image')} Add a photo, if you’d like</span></label><span class="help-text">JPG, PNG or WebP · up to 15 MB. Photos are resized to save space.</span><p class="form-error" id="form-error" role="alert"></p><div class="modal-actions">${btn('Cancel','close','secondary')}<button type="submit" class="button">${icon('heart')} Keep this moment</button></div></form>`);}
function newNote(){const a=esc(state.profile.one),b=esc(state.profile.two);openDialog(`${modalHeader('A little love, folded up.')}<form id="note-form" class="modal-body"><div class="form-row"><label class="field"><span>From</span><select name="from"><option value="${a}">${a}</option><option value="${b}">${b}</option></select></label><label class="field"><span>For</span><select name="to"><option value="${b}">${b}</option><option value="${a}">${a}</option><option value="us">us</option></select></label></div><label class="field"><span>Say the sweet thing</span><textarea name="body" maxlength="5000" style="min-height:180px" placeholder="I don’t say this enough, but..." required></textarea></label><span class="help-text">It’ll stay folded until one of you taps to open it.</span><p class="form-error" id="form-error" role="alert"></p><div class="modal-actions">${btn('Cancel','close','secondary')}<button type="submit" class="button">${icon('mail')} Fold with love</button></div></form>`);}
function readMemory(id){const m=state.memories.find(x=>x.id===id);if(!m)return;openDialog(`${modalHeader(esc(m.title),'A MOMENT THAT’S OURS')}<div class="modal-body"><div class="date-label">${esc(dateLabel(m.date))} · ${names()}</div>${m.photo?`<img class="read-photo" src="${esc(m.photo)}" alt="${esc(m.title)}">`:''}<div class="memory-reading">${esc(m.body||'A little moment, a lot of love.')}</div><div class="modal-actions"><button class="text-button danger" data-action="delete-memory" data-id="${esc(id)}">Delete memory</button>${btn('Keep it close','close','secondary','heart')}</div></div>`);}
function readNote(id){const n=state.notes.find(x=>x.id===id);if(!n)return;openDialog(`${modalHeader(`For ${esc(n.to)},`,'YOU’VE GOT A LITTLE LOVE')}<div class="modal-body"><div class="note-reading">${esc(n.body)}</div><div class="note-signature">Always, ${esc(n.from)} ♡</div><p class="date-label" style="margin-top:18px">${esc(dateLabel(n.date))}</p><div class="modal-actions"><button class="text-button danger" data-action="delete-note" data-id="${esc(id)}">Delete note</button>${btn('Fold it back up','close','secondary','mail')}</div></div>`);}
const prompts=[
['Little things','What’s one tiny thing I do that makes you feel loved?'],['Our story','What’s a very ordinary moment with me that you wish you could replay?'],['A little silly','If we were two cats, where would our favorite napping spot be?'],['Looking ahead','What does our perfect slow Sunday look like, five years from now?'],['Little things','Finish this sentence: “I feel closest to you when...”'],['Our story','When did you first catch yourself smiling because of me?'],['A little silly','Give our relationship a very dramatic movie title.'],['Soft & honest','What’s something you’d love a little more of from me lately?'],['Our story','What’s an inside joke that only we would understand?'],['Looking ahead','What tiny tradition should we start, just for us?'],['Little things','What’s something about me you hope never changes?'],['Soft & honest','How can I make a hard day feel a little softer for you?'],['A little silly','What would be our completely useless couple superpower?'],['Our story','What was your first impression of me—and what surprised you later?'],['Little things','What’s your favorite version of us: sleepy, silly, clingy, or adventurous? Why?'],['Looking ahead','If we had a whole day with no responsibilities, what would we do?'],['Soft & honest','What’s one thing you’ve been wanting to tell me?'],['A little silly','Invent an extremely cheesy nickname for me. Defend your choice.'],['Our story','Which song feels like a little piece of our story?'],['Little things','What’s a small thing we do together that you’d miss the most?'],['Looking ahead','Where should we watch a sunset together someday?'],['Soft & honest','What helps you feel heard when something is on your mind?'],['A little silly','If we opened a tiny shop together, what would we sell?'],['Little things','Tell me three oddly specific things you adore about me.'],['Our story','What’s something we’ve learned to do better as a team?'],['Looking ahead','What’s a simple date you’d love us to repeat?'],['Soft & honest','What’s one thing you’re proud of us for?'],['A little silly','Describe me using only three food names. Explain absolutely nothing.']];
function nextPrompt(){if(!promptDeck.length){promptDeck=prompts.map((_,i)=>i);for(let i=promptDeck.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[promptDeck[i],promptDeck[j]]=[promptDeck[j],promptDeck[i]];}promptCount=0;}const p=prompts[promptDeck.pop()];promptCount++;openDialog(`${modalHeader('A little closer.','JUST YOU, ME & A QUESTION')}<div class="prompt-body"><div class="prompt-category">${p[0]}</div><div class="prompt-question">${p[1]}</div><p class="prompt-tip">One of you answers. Then swap.<br>No perfect answers. No rush. Just listen.</p>${btn('One more question','prompt','','spark')}<p class="prompt-progress">${promptCount} OF ${prompts.length} LITTLE CONVERSATIONS</p></div>`);}
const dates=[
['☕','The living room café','Make each other a drink. Put on a song you both love. Ask: “What was the best bit of your week?” Pretend there’s nowhere else to be.','15–30 minutes · at home'],['☾','Same window, same moon','Find a window or a comfortable spot outside. Sit close for five quiet minutes. Then each share one thing you’re looking forward to together.','10 minutes · wherever you are'],['✎','The three-line love letter','Each write three lines: one thing you noticed, one thing you appreciate, and one tiny wish for us. Read them aloud—or leave them in our notes.','15 minutes · sweet & cheesy'],['♫','Our two-song concert','Each choose one song: a song that reminds you of us, and a song you want to share. Listen together and tell the story behind your choices.','20 minutes · music & memories'],['♡','Five photos, five stories','Open your camera rolls. Each pick five photos that make you smile. Trade the phone and tell the stories, even the blurry ones.','20 minutes · nostalgic'],['✧','Our very unserious awards','Give each other three silly awards. Best sleepy face? Most dramatic snack request? Make acceptance speeches compulsory.','15 minutes · very silly'],['☁','Build a little nest','Gather the softest blankets and pillows. Pick a snack. Spend ten minutes cuddled up with no scrolling and no agenda.','15 minutes · maximum cozy'],['✦','The tiny future list','Write five small things you want to do together this month. Each choose one favorite. Put the first one on your calendar.','15 minutes · dreaming together'],['☕','Snack tasting, but fancy','Find three snacks you already have. Plate them dramatically. Rate each for crunch, comfort, and date-night potential. Very serious reviews only.','20 minutes · snacks encouraged'],['✎','Draw me, terribly','Set a two-minute timer and draw each other without looking at the paper. Swap masterpieces. Add a ridiculously romantic caption.','10 minutes · paper & pen'],['☾','The slow dance','Choose one soft song. Dance in the living room, kitchen, or wherever you fit. Being good at dancing is entirely optional.','One song · wonderfully cheesy'],['♡','Remember our firsts','Take turns naming a first: first laugh, first favorite meal, first little adventure. Pick one you’d love to recreate.','15 minutes · all the feelings']];
function nextDate(){let idx=Math.floor(Math.random()*dates.length);if(idx===lastDate)idx=(idx+1)%dates.length;lastDate=idx;const d=dates[idx];openDialog(`${modalHeader('Tonight, let’s...','A LITTLE SOMETHING FROM THE DATE JAR')}<div class="modal-body center"><div class="date-icon" aria-hidden="true">${d[0]}</div><h3 class="date-title">${d[1]}</h3><p class="date-description">${d[2]}</p><div class="date-meta">${d[3]}</div><div class="actions" style="justify-content:center">${btn('Another little idea','date','secondary','spark')}${btn('It’s a date ♡','accept-date')}</div></div>`);}
function settings(){openDialog(`${modalHeader('Make it ours.','OUR LITTLE WORLD')}<div class="modal-body"><form id="profile-form"><div class="form-row"><label class="field"><span>Your name</span><input name="one" maxlength="30" value="${esc(state.profile.one)}" required></label><label class="field"><span>Your person</span><input name="two" maxlength="30" value="${esc(state.profile.two)}" required></label></div><label class="field"><span>Our anniversary <small style="display:inline">(optional)</small></span><input name="anniversary" type="date" max="${today()}" value="${esc(state.profile.anniversary)}"><small>We’ll count the days of choosing each other.</small></label><p class="form-error" id="form-error" role="alert"></p><button class="button" type="submit">Save our little details</button></form><div class="settings-section"><h3>Keep our keepsakes safe</h3><p>Memories and notes stay in this browser on this device. They won’t sync to another phone or browser. Clearing browser data can erase them, so download a backup once in a while.</p><div class="backup-actions">${btn('Download backup','backup','secondary','download')}<label class="button secondary file-button" tabindex="0" role="button">Restore backup<input id="restore-input" type="file" accept=".json,application/json" aria-label="Choose backup file"></label></div><p>Backups contain your photos and notes. Store them somewhere private.</p>${loadError?`<p class="form-error">${esc(loadError)}</p>`:''}</div></div>`);}
async function loadPhoto(file){if(!file)return;const form=$('#memory-form'),error=$('#form-error'),submit=form.querySelector('[type="submit"]');photoBusy=true;submit.disabled=true;error.textContent='';try{if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Please choose a JPG, PNG or WebP photo.');if(file.size>15*1024*1024)throw Error('Choose a photo smaller than 15 MB.');const bitmap=await createImageBitmap(file);try{const scale=Math.min(1,1200/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#eee4ed';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);const data=canvas.toDataURL('image/jpeg',.78);if(data.length>2000000)throw Error('This photo is still too large. Try a smaller one.');if(form.isConnected){photoDraft=data;$('#photo-preview').innerHTML=`<img class="upload-preview" src="${data}" alt="Selected photo preview"><span class="help-text">${esc(file.name)}</span>`;}}finally{bitmap.close();}}catch(e){if(form.isConnected)error.textContent=e.message||'That photo couldn’t be opened. Try another one.';}finally{if(form.isConnected){photoBusy=false;submit.disabled=false;}}}
function backup(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`our-little-world-${today()}.json`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Backup downloaded. Keep it somewhere safe ♡');}
async function restore(file){if(!file)return;try{if(file.size>10*1024*1024)throw Error('This backup is too large. Choose an Our Little World JSON backup under 10 MB.');const imported=validate(JSON.parse(await file.text()));if(!confirm(`Restore ${imported.memories.length} memories and ${imported.notes.length} notes? This replaces what’s currently in this browser. Download a backup first if you want to keep the current collection.`))return;const clean=save(localStorage,imported);state=clean;loadError='';render();modal.close();notify('Your little world is back where it belongs ♡');}catch(e){notify(e instanceof SyntaxError?'That file couldn’t be read. Choose an Our Little World JSON backup.':e.message);}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const action=el.dataset.action,id=el.dataset.id;try{if(action==='close')modal.close();else if(action==='new-note')newNote();else if(action==='new-memory')newMemory();else if(action==='memory')readMemory(id);else if(action==='note')readNote(id);else if(action==='prompt')nextPrompt();else if(action==='date')nextDate();else if(action==='settings')settings();else if(action==='backup')backup();else if(action==='accept-date'){modal.close();notify('It’s a date. Go be disgustingly cute together ♡');}else if(action==='delete-memory'||action==='delete-note'){const type=action==='delete-memory'?'memories':'notes';if(confirm(`Delete this ${type==='notes'?'note':'memory'}? This can’t be undone without a backup.`)){commit(s=>s[type]=s[type].filter(x=>x.id!==id));modal.close();notify('Removed from your little world.');}}}catch(error){notify(error.message);}});
document.addEventListener('submit',e=>{const form=e.target;if(!['note-form','memory-form','profile-form'].includes(form.id))return;e.preventDefault();const values=Object.fromEntries(new FormData(form));try{if(form.id==='memory-form'){if(photoBusy)throw Error('Your photo is still being prepared. One moment.');if(!values.title.trim())throw Error('Give this memory a little name.');if(values.date>today())throw Error('Choose today or an earlier day for a memory.');commit(s=>s.memories.unshift({id:crypto.randomUUID(),title:values.title.trim(),body:values.body.trim(),date:values.date,photo:photoDraft}));modal.close();notify('A little piece of forever, kept ♡');}else if(form.id==='note-form'){if(!values.body.trim())throw Error('Add a few words of love first.');commit(s=>s.notes.unshift({id:crypto.randomUUID(),from:values.from,to:values.to,body:values.body.trim(),date:today()}));modal.close();notify('Folded with love. Ready for your favorite human ♡');}else{if(!values.one.trim()||!values.two.trim())throw Error('Add both of your names.');if(values.anniversary>today())throw Error('Choose today or an earlier day for your anniversary.');commit(s=>s.profile={one:values.one.trim(),two:values.two.trim(),anniversary:values.anniversary});modal.close();notify('A little more you two ♡');}}catch(error){$('#form-error').textContent=error.message;}});
document.addEventListener('change',e=>{if(e.target.id==='photo-input')loadPhoto(e.target.files[0]);if(e.target.id==='restore-input')restore(e.target.files[0]);if(e.target.name==='from'&&e.target.closest('#note-form')){const recipient=$('#note-form [name="to"]');recipient.value=e.target.value===state.profile.one?state.profile.two:state.profile.one;}});
document.addEventListener('keydown',e=>{if(e.target.classList.contains('file-button')&&(e.key==='Enter'||e.key===' ')){e.preventDefault();e.target.querySelector('input').click();}});
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close();}});
window.addEventListener('hashchange',()=>{if(modal.open)modal.close();render();window.scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true});});
window.addEventListener('storage',e=>{if(e.key===KEY){loadError='Your world changed in another tab. Reload this page before adding anything else so all your keepsakes stay together.';notify(loadError);}});
render();if(loadError)notify(loadError);
